# ── Mode-note sidecar (composer-modes v11): per-turn notes staged by the Desktop plugin and
# merged ONLY into the model-facing api_content (never into the durable user row). ──
_STAGED_NOTE_TTL_S = 30.0
_STAGED_NOTES: dict[str, tuple[str, float]] = {}


def _pop_staged_note(sid: str) -> str | None:
    """Pop a staged note at most once; entries older than the TTL are discarded."""
    entry = _STAGED_NOTES.pop(sid, None)
    if not entry:
        return None
    note, staged_at = entry
    if (time.time() - staged_at) > _STAGED_NOTE_TTL_S:
        return None
    return note


@method("session.note.stage")
def _(rid, params: dict) -> dict:
    """Stage the NEXT prompt's hidden mode note for a session (one-shot, TTL-bounded). The note
    merges only into the model-facing api_content of that turn — it never reaches the transcript
    row, so the user's bubble stays exactly what they typed."""
    from hermes_cli.input_sanitize import sanitize_user_prompt_text
    raw_note = params.get("note")
    note = sanitize_user_prompt_text(raw_note).strip() if isinstance(raw_note, str) else ""
    if not note:
        return _err(rid, 4126, "note is required")
    if len(note) > 8192:
        note = note[:8192]
    _session, err = _sess_nowait(params, rid)
    if err:
        return err
    _STAGED_NOTES[params.get("session_id", "")] = (note, time.time())
    return _ok(rid, {"status": "staged", "ttl_s": _STAGED_NOTE_TTL_S})


